"""Browser-storage key registry template (static).

One scheme for every key the framework writes: `cfg.<area>.<name>`, lower
case, dots between levels, `snake_case` inside a level. The emitted
`helpers/keys.ts` holds the key table, the guarded storage helpers, the
`createStorage(owner)`, which
gives an app the same helpers under its own prefix.
"""

KEYS_TS = '''\
// AUTO-GENERATED by django_generator / ts_extras.wrapper
// Browser-storage key registry: one scheme, guarded access.
// DO NOT EDIT — re-run `make gen`.
//
// Rules for agents and apps: @docs/STORAGE_KEYS.md in @djangocfg/api.
//
// Scheme: `<owner>.<area>.<name>` — lower case, dots between levels,
// `snake_case` inside a level. The framework's owner is `cfg`; an app picks its
// own with `createStorage('<owner>')`. Third-party keys (a library's own
// prefix, `NEXT_LOCALE`) are not ours to rename and stay as they are.

export type KeyStore = 'local' | 'session' | 'cookie';

export interface KeySpec {
  /** The canonical key. */
  readonly key: string;
  readonly store: KeyStore;
  /** Removed by `clearAll()` (sign-out). Preferences are kept. */
  readonly personal: boolean;
}

export interface FamilySpec {
  /** Canonical prefix ending in a dot; the id is appended in normalised form. */
  readonly prefix: string;
  readonly store: 'local' | 'session';
  readonly personal: boolean;
}

const k = (
  key: string,
  store: KeyStore,
  personal: boolean,
): KeySpec => ({ key, store, personal });

const f = (
  prefix: string,
  store: 'local' | 'session',
  personal: boolean,
): FamilySpec => ({ prefix, store, personal });

/** Every key the framework writes. No legacy spellings are read: old keys are simply ignored. */
export const CFG_KEYS = {
  accessToken: k('cfg.auth.access_token', 'cookie', true),
  refreshToken: k('cfg.auth.refresh_token', 'cookie', true),
  apiKey: k('cfg.auth.api_key', 'local', true),
  email: k('cfg.auth.email', 'local', false),
  emailTs: k('cfg.auth.email_ts', 'local', false),
  redirectUrl: k('cfg.auth.redirect_url', 'session', true),
  redirectUrlTs: k('cfg.auth.redirect_url_ts', 'session', true),
  oauthState: k('cfg.auth.oauth_state', 'session', true),
  oauthProvider: k('cfg.auth.oauth_provider', 'session', true),
  oauthProviders: k('cfg.auth.oauth_providers', 'session', false),
  profileCache: k('cfg.profile.cache', 'local', true),
  monitorSessionId: k('cfg.monitor.session_id', 'local', false),
  monitorSessionCookie: k('cfg.monitor.session_id', 'cookie', false),
  monitorDebug: k('cfg.monitor.debug', 'local', false),
  clientId: k('cfg.client.id', 'local', false),
  uiTabId: k('cfg.ui.tab_id', 'session', false),
  uiRouterSerial: k('cfg.ui.router_serial', 'session', false),
  uiState: k('cfg.ui.state', 'local', false),
  chatSpeechLanguage: k('cfg.chat.speech_language', 'local', false),
  chatRecentTools: k('cfg.chat.recent_tools', 'local', false),
  formsSpeechDebug: k('cfg.forms.speech_debug', 'local', false),
  formsSpeechPrefs: k('cfg.forms.speech_prefs', 'local', false),
  agentPlaygroundApiKeyId: k('cfg.agent.playground_api_key_id', 'session', true),
  agentPlaygroundBearer: k('cfg.agent.playground_bearer', 'session', true),
  agentEndpointDoc: k('cfg.agent.endpoint_doc', 'session', false),
} as const satisfies Record<string, KeySpec>;

/** Keys with a caller-supplied id part: one per room, tree, endpoint. */
export const CFG_FAMILIES = {
  chatDraft: f('cfg.chat.draft.', 'session', true),
  dataTree: f('cfg.data.tree.', 'local', false),
  agentEndpointDraft: f('cfg.agent.endpoint_draft.', 'local', false),
} as const satisfies Record<string, FamilySpec>;

const OWNER_RE = /^[a-z][a-z0-9_]*$/;

/** One segment of a key: lower case, `[a-z0-9_]`, anything else folded to `_`. */
export function normalizeSegment(raw: string): string {
  return raw
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

export interface StorageOptions {
  /** Named keys of this owner. */
  readonly keys?: Readonly<Record<string, KeySpec>>;
  readonly families?: Readonly<Record<string, FamilySpec>>;
  /** Cookie lifetime for the `cookie` store. Default 30 days. */
  readonly cookieMaxAgeSeconds?: number;
  /**
   * Cookie `Domain`. `'auto'` (default): the registrable domain of the page, so every subdomain
   * shares the cookie (`example.com` for `my.example.com`). A string forces a domain; `false`
   * keeps cookies host-only.
   */
  readonly cookieDomain?: 'auto' | string | false;
}

export interface WriteOptions {
  /** Cookie store: lifetime of this write. Default: the owner's `cookieMaxAgeSeconds`. */
  readonly maxAgeSeconds?: number;
}

export interface GuardedStorage {
  readonly owner: string;
  /** Builds `<owner>.<part>.<part>` from free-form parts; throws if a part is empty. */
  key(...parts: string[]): string;
  /** Builds a family member key: the prefix plus the normalised id. */
  familyKey(family: FamilySpec, id: string): string;
  /** `^(cfg|<owner>)(\\.[a-z0-9_]+)+$`. */
  isValid(key: string): boolean;
  read(key: string, store?: KeyStore): string | null;
  /** True when the value reached the browser's storage; false means it is held in memory for this page only. */
  write(key: string, value: string, store?: KeyStore, options?: WriteOptions): boolean;
  /** Removes the key. */
  remove(key: string, store?: KeyStore): void;
  readJSON<T>(key: string, store?: KeyStore): T | null;
  writeJSON(key: string, value: unknown, store?: KeyStore): boolean;
  /** Keys this owner holds in `store`. */
  keys(store?: Exclude<KeyStore, 'cookie'>): string[];
  /** Sign-out: removes the `personal` keys. `{ all: true }` removes everything under this owner. */
  clearAll(options?: { all?: boolean }): void;
  /** Cookie store: change the `Domain` policy (`'auto'`, a domain, or `false` for host-only cookies). */
  setCookieDomain(domain: 'auto' | string | false): void;
  /** The `Domain` cookies are written with right now; `null` means host-only. */
  cookieDomain(): string | null;
  /** Cross-tab: calls `listener` with the new value when ANOTHER tab changes `key`. Cookies fire no events. */
  onChange(key: string, listener: (value: string | null) => void, store?: Exclude<KeyStore, 'cookie'>): () => void;
}

const hasWindow = () => typeof window !== 'undefined';

const domainByHost = new Map<string, string | null>();

/**
 * The broadest domain this page may set cookies on (`example.com` for `my.example.com`,
 * `example.co.uk` for `a.example.co.uk`), found by asking the browser: it refuses a cookie for a
 * public suffix, so no suffix list lives in our code. `null` for an IP, `localhost`, a single label
 * or when cookies are blocked (the cookie is then host-only).
 */
function detectCookieDomain(): string | null {
  if (!hasWindow() || typeof document === 'undefined') return null;
  const host = window.location.hostname.toLowerCase();
  if (!host || !host.includes('.') || host.includes(':') || /^[0-9.]+$/.test(host)) return null;
  const cached = domainByHost.get(host);
  if (cached !== undefined) return cached;
  const labels = host.split('.');
  const secure = window.location.protocol === 'https:' ? '; Secure' : '';
  let found: string | null = null;
  try {
    for (let i = labels.length - 2; i >= 0 && found === null; i -= 1) {
      const candidate = labels.slice(i).join('.');
      const probe = 'cfg_probe_' + Math.random().toString(36).slice(2);
      document.cookie = probe + '=1; Domain=' + candidate + '; Path=/; Max-Age=30; SameSite=Lax' + secure;
      if (document.cookie.includes(probe + '=1')) found = candidate;
      document.cookie = probe + '=; Domain=' + candidate + '; Path=/; Max-Age=0; SameSite=Lax' + secure;
    }
  } catch {
    found = null;
  }
  domainByHost.set(host, found);
  return found;
}

function nativeStorage(store: 'local' | 'session'): Storage | null {
  if (!hasWindow()) return null;
  try {
    return store === 'session' ? window.sessionStorage : window.localStorage;
  } catch {
    return null;
  }
}

function cookieNames(): string[] {
  if (!hasWindow()) return [];
  try {
    return document.cookie
      .split('; ')
      .map((part) => decodeURIComponent(part.split('=')[0] ?? ''))
      .filter(Boolean);
  } catch {
    return [];
  }
}

export function createStorage(owner: string, options: StorageOptions = {}): GuardedStorage {
  if (!OWNER_RE.test(owner)) {
    throw new TypeError(`createStorage: owner "${owner}" must match ${OWNER_RE}`);
  }
  const prefix = `${owner}.`;
  const pattern = owner === 'cfg' ? /^cfg(\\.[a-z0-9_]+)+$/ : new RegExp(`^(cfg|${owner})(\\\\.[a-z0-9_]+)+$`);
  const cookieMaxAge = options.cookieMaxAgeSeconds ?? 60 * 60 * 24 * 30;
  let cookiePolicy: 'auto' | string | false = options.cookieDomain ?? 'auto';
  const resolveCookieDomain = (): string | null =>
    cookiePolicy === false ? null : cookiePolicy === 'auto' ? detectCookieDomain() : cookiePolicy;
  // A cookie is identified by name AND Domain: expire the twin without a domain and the one with it.
  const expireCookie = (key: string, domain: string | null) => {
    const secure = window.location.protocol === 'https:' ? '; Secure' : '';
    document.cookie =
      encodeURIComponent(key) + '=; Path=/; Max-Age=0; SameSite=Lax' + (domain ? '; Domain=' + domain : '') + secure;
  };
  const specs = Object.values(options.keys ?? {});
  const families = Object.values(options.families ?? {});
  const specByKey = new Map<string, KeySpec[]>();
  for (const spec of specs) specByKey.set(spec.key, [...(specByKey.get(spec.key) ?? []), spec]);
  // Held in memory when the browser refuses a write (quota, private mode), so the page still works until reload.
  const memory: Record<KeyStore, Map<string, string>> = {
    local: new Map(),
    session: new Map(),
    cookie: new Map(),
  };

  const isValid = (key: string) => pattern.test(key);
  const assertValid = (key: string) => {
    if (!isValid(key)) throw new TypeError(`storage key "${key}" must match ${pattern}`);
  };
  const assertOwned = (key: string) => {
    assertValid(key);
    if (!key.startsWith(prefix)) throw new TypeError(`storage key "${key}" is not owned by "${owner}"`);
  };

  function rawGet(store: KeyStore, key: string): string | null {
    if (!hasWindow()) return null;
    if (store === 'cookie') {
      try {
        const escaped = encodeURIComponent(key).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');
        const match = document.cookie.match(new RegExp(`(?:^|;\\\\s*)${escaped}=([^;]*)`));
        if (match?.[1] !== undefined) return decodeURIComponent(match[1]);
      } catch {
        /* fall through to memory */
      }
      return memory.cookie.get(key) ?? null;
    }
    try {
      const value = nativeStorage(store)?.getItem(key) ?? null;
      if (value !== null) return value;
    } catch {
      /* fall through to memory */
    }
    return memory[store].get(key) ?? null;
  }

  function rawSet(store: KeyStore, key: string, value: string, maxAgeSeconds?: number): boolean {
    if (!hasWindow()) return false;
    try {
      if (store === 'cookie') {
        const secure = window.location.protocol === 'https:' ? '; Secure' : '';
        const domain = resolveCookieDomain();
        const domainPart = domain ? `; Domain=${domain}` : '';
        document.cookie = `${encodeURIComponent(key)}=${encodeURIComponent(value)}; Path=/; Max-Age=${Math.max(1, Math.floor(maxAgeSeconds ?? cookieMaxAge))}; SameSite=Lax${domainPart}${secure}`;
        // A host-only cookie written earlier would shadow the shared one: drop that twin.
        if (domain) expireCookie(key, null);
        if (rawGet('cookie', key) === value && !memory.cookie.has(key)) return true;
        memory.cookie.set(key, value);
        return false;
      }
      const native = nativeStorage(store);
      if (!native) throw new Error('storage unavailable');
      native.setItem(key, value);
      memory[store].delete(key);
      return true;
    } catch {
      memory[store].set(key, value);
      return false;
    }
  }

  function rawRemove(store: KeyStore, key: string): void {
    memory[store].delete(key);
    if (!hasWindow()) return;
    try {
      if (store === 'cookie') {
        expireCookie(key, null);
        const domain = resolveCookieDomain();
        if (domain) expireCookie(key, domain);
      } else {
        nativeStorage(store)?.removeItem(key);
      }
    } catch {
      /* ignore */
    }
  }

  function resolveStore(key: string, store?: KeyStore): KeyStore {
    return store ?? specByKey.get(key)?.[0]?.store ?? 'local';
  }

  function listKeys(store: 'local' | 'session', startsWith: string): string[] {
    const out: string[] = [];
    try {
      const native = nativeStorage(store);
      if (native) {
        for (let i = 0; i < native.length; i += 1) {
          const name = native.key(i);
          if (name?.startsWith(startsWith)) out.push(name);
        }
      }
    } catch {
      /* ignore */
    }
    for (const name of memory[store].keys()) if (name.startsWith(startsWith) && !out.includes(name)) out.push(name);
    return out;
  }

  const familyKey = (family: FamilySpec, id: string) => {
    const part = normalizeSegment(id);
    if (!part) throw new TypeError('storage family id is empty after normalisation');
    return family.prefix + part;
  };

  const api: GuardedStorage = {
    owner,
    key(...parts) {
      const segments = parts.map(normalizeSegment);
      if (segments.length === 0 || segments.some((segment) => !segment)) {
        throw new TypeError(`storage key parts must be non-empty: ${JSON.stringify(parts)}`);
      }
      return `${prefix}${segments.join('.')}`;
    },
    familyKey,
    isValid,
    read(key, store) {
      assertValid(key);
      const target = resolveStore(key, store);
      return rawGet(target, key);
    },
    write(key, value, store, writeOptions) {
      assertOwned(key);
      const target = resolveStore(key, store);
      return rawSet(target, key, value, writeOptions?.maxAgeSeconds);
    },
    remove(key, store) {
      assertOwned(key);
      const target = resolveStore(key, store);
      rawRemove(target, key);
    },
    readJSON<T>(key: string, store?: KeyStore): T | null {
      const raw = api.read(key, store);
      if (raw === null) return null;
      try {
        return JSON.parse(raw) as T;
      } catch {
        return null;
      }
    },
    writeJSON(key, value, store) {
      return api.write(key, JSON.stringify(value), store);
    },
    keys(store = 'local') {
      return listKeys(store, prefix);
    },
    clearAll({ all = false } = {}) {
      for (const spec of specs) {
        if (!all && !spec.personal) continue;
        rawRemove(spec.store, spec.key);
      }
      for (const family of families) {
        if (!all && !family.personal) continue;
        for (const name of listKeys(family.store, family.prefix)) rawRemove(family.store, name);
      }
      if (all) {
        for (const store of ['local', 'session'] as const) {
          for (const name of listKeys(store, prefix)) rawRemove(store, name);
        }
        for (const name of cookieNames()) if (name.startsWith(prefix)) rawRemove('cookie', name);
      }
    },
    setCookieDomain(domain) {
      cookiePolicy = domain;
    },
    cookieDomain: resolveCookieDomain,
    onChange(key, listener, store = 'local') {
      assertValid(key);
      if (!hasWindow()) return () => {};
      const handler = (event: StorageEvent) => {
        if (event.storageArea !== nativeStorage(store)) return;
        if (event.key === null || event.key === key) listener(event.key === null ? null : event.newValue);
      };
      window.addEventListener('storage', handler);
      return () => window.removeEventListener('storage', handler);
    },
  };
  return api;
}

/** The framework's own storage: every `cfg.*` key. */
export const cfgStorage: GuardedStorage = createStorage('cfg', {
  keys: CFG_KEYS,
  families: CFG_FAMILIES,
});

'''
